"""Shared rule engine used by the per-service normalizers."""

from datetime import date
from decimal import Decimal, ROUND_HALF_UP

_TRUE = ("yes", "true", "1")
_FALSE = ("no", "false", "0")


def _require(record, field):
    if field not in record:
        raise ValueError("missing required field: %s" % field)


def _default(record, field, value):
    if field not in record:
        record[field] = value


def _call(record, field, method):
    if field not in record:
        return
    value = record[field]
    if not isinstance(value, str):
        value = str(value)
    record[field] = getattr(value, method)()


def _rename(record, source, target):
    if source in record:
        record[target] = record.pop(source)


def _drop(record, field):
    record.pop(field, None)


def _cents(record, field):
    if field not in record:
        return
    amount = Decimal(str(record[field]).strip())
    record[field] = int((amount * 100).quantize(Decimal(1), rounding=ROUND_HALF_UP))


def _bool(record, field):
    if field not in record:
        return
    text = "".join(str(record[field]).split()).lower()
    if text in _TRUE:
        record[field] = True
    elif text in _FALSE:
        record[field] = False
    else:
        raise ValueError("not a boolean value: %r" % (record[field],))


def _iso_date(record, field):
    if field not in record:
        return
    text = "".join(str(record[field]).split())
    day, month, year = text.split("/")
    record[field] = date(int(year), int(month), int(day)).isoformat()


def _split(record, field, separator):
    if field not in record:
        return
    value = record[field]
    if not isinstance(value, str):
        value = str(value)
    record[field] = [piece.strip() for piece in value.split(separator) if piece.strip()]


def apply_rules(record, rules):
    """Return a normalized copy of record after applying rules in order."""
    result = dict(record)
    for rule in rules:
        operator = rule[0]
        if operator == "require":
            _require(result, rule[1])
        elif operator == "default":
            _default(result, rule[1], rule[2])
        elif operator in ("strip", "lower", "upper"):
            _call(result, rule[1], operator)
        elif operator == "rename":
            _rename(result, rule[1], rule[2])
        elif operator == "drop":
            _drop(result, rule[1])
        elif operator == "cents":
            _cents(result, rule[1])
        elif operator == "bool":
            _bool(result, rule[1])
        elif operator == "iso-date":
            _iso_date(result, rule[1])
        elif operator == "split":
            _split(result, rule[1], rule[2])
        else:
            raise ValueError("unknown rule: %r" % (rule,))
    return result

